function artifact=aggregateV4BCalibration()
root=v4SetupPaths();folder=fullfile(root,'results','calibration','track_b','B-param-v01','candidates');records=repmat(struct(),32,1);for i=1:32,x=load(fullfile(folder,sprintf('candidate_%02d.mat',i)),'record');if i==1,records=repmat(x.record,32,1);end;records(i)=x.record;end;valid=find([records.passed]);if isempty(valid),selected=NaN;else,coverage=reshape([records(valid).coverage],[],1);rmse=reshape([records(valid).cfoRmseBins],[],1);candidate=valid(:);score=[-coverage rmse candidate];[~,order]=sortrows(score,[1 2 3]);selected=valid(order(1));end;list=v4BCalibrationCandidates();artifact=struct('status',ternary(isfinite(selected),'PASS','FAIL'),'algorithmVersion','Stage55-B-project-path-calibrated-v7','candidateCount',32,'calibrationFramesPerCandidate',32,'selectedCandidateIndex',selected,'records',records,'selectionUsesSerOrBer',false,'parameters',pick(list,selected),'conditionsFrozen',true);out=fileparts(folder);save(fullfile(out,'calibration.mat'),'artifact','-v7.3');write(fullfile(out,'calibration.json'),jsonencode(artifact,'PrettyPrint',true));if ~isfinite(selected),error('V4:BCalibration','No B candidate passed.');end
end
function x=ternary(ok,a,b),if ok,x=a;else,x=b;end,end
function x=pick(c,i),if isfinite(i),x=c(i);else,x=struct();end,end
function write(path,text),f=fopen(path,'w','n','UTF-8');cl=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear cl,end
